// Some portions generated by Claude
/**
 * The readability pass moves cards off straight lines, but arrows are drawn as routed curves: a curve can still cross
 * a card the straight line missed, and the router cannot always bend around a crowd. This pass routes the arrows,
 * finds cards a curve still crosses, and moves each such card a short way off the curve when that keeps card clearance,
 * adds no crossing or straight edge through a card, and leaves the card crossed by fewer routed arrows.
 */
import { withCollapsedClassLinks } from './graph-class-links.ts';
import { quadraticIntersectsBounds } from './graph-curve-collision.ts';
import { computeEdgePorts, edgeGeometry, edgePortKey, graphNodeSize, optimizeEdgeBends, quadraticPoint } from './graph-geometry.ts';
import { layoutNodeFixed } from './graph-layout-topology.ts';
import { LAYOUT_SPACING as gap } from './graph-layout-spacing.ts';
import { segmentIntersectsBounds } from './graph-curve-collision.ts';
import { isStatementLinkEdge } from './statement-links.ts';
import type { EdgeCurve, Graph, GraphEdge, PointerPosition } from './graph-types.ts';
import type { LayoutOptions } from './graph-layout-engine.ts';

/** Hubs with more links stay put: moving one would drag a whole fan of arrows across the drawing. */
const MOVABLE_DEGREE_LIMIT = 24;
const STEPS = [36, 72, 120, 180, 260, 340, 440];

/** The edges the canvas draws and routes: no statement-link springs, no collapsed class links. */
export function routedEdgesOf(graph: Graph): GraphEdge[] {
  return withCollapsedClassLinks(graph).graph.edges.filter(edge => !isStatementLinkEdge(edge));
}

/** Routing passes the layout uses for this many edges. */
export const routingPasses = (edgeCount: number, preferred: number) =>
  edgeCount <= 500 ? Math.min(preferred, 2) : edgeCount <= 1600 ? Math.min(preferred, 1) : 0;

export function repairRoutedObstructions(graph: Graph, positions: Map<string, PointerPosition>, options: LayoutOptions = {}) {
  const edges = routedEdgesOf(graph).filter(edge => edge.source !== edge.target && positions.has(edge.source) && positions.has(edge.target));
  if (graph.nodes.length > 350 || edges.length > 500 || !edges.length || options.groups?.length) return 0;
  const byId = new Map(graph.nodes.map(node => [node.id, node]));
  const sizes = new Map(graph.nodes.map(node => [node.id, graphNodeSize(node)]));
  const degree = new Map<string, number>();
  for (const edge of edges) for (const id of [edge.source, edge.target]) degree.set(id, (degree.get(id) ?? 0) + 1);
  const body = (id: string, at: PointerPosition, padding = 0) => {
    const size = sizes.get(id)!;
    return {minX: at.x - size.width / 2 - padding, minY: at.y - size.height / 2 - padding, maxX: at.x + size.width / 2 + padding, maxY: at.y + size.height / 2 + padding};
  };
  const tooClose = (a: string, p: PointerPosition, b: string, q: PointerPosition) => {
    const sa = sizes.get(a)!, sb = sizes.get(b)!;
    return Math.abs(p.x - q.x) < (sa.width + sb.width) / 2 + gap.nodeGapX && Math.abs(p.y - q.y) < (sa.height + sb.height) / 2 + gap.nodeGapY;
  };
  const crosses = (a: PointerPosition, b: PointerPosition, c: PointerPosition, d: PointerPosition) => {
    const o = (p: PointerPosition, q: PointerPosition, r: PointerPosition) => (q.x - p.x) * (r.y - p.y) - (q.y - p.y) * (r.x - p.x);
    return o(a, b, c) * o(a, b, d) < -1e-6 && o(c, d, a) * o(c, d, b) < -1e-6;
  };
  /** Straight-line conflicts that moving `id` can change. */
  const straightConflicts = (id: string, at: PointerPosition) => {
    const where = (other: string) => (other === id ? at : positions.get(other)!);
    let count = 0;
    for (const edge of edges) {
      const touches = edge.source === id || edge.target === id;
      const a = where(edge.source), b = where(edge.target);
      if (touches) {
        for (const other of edges) {
          if (other === edge || other.source === edge.source || other.source === edge.target || other.target === edge.source || other.target === edge.target) continue;
          if (crosses(a, b, where(other.source), where(other.target))) count++;
        }
        for (const other of positions.keys()) if (other !== edge.source && other !== edge.target && segmentIntersectsBounds(a, b, body(other, where(other)))) count++;
      } else if (segmentIntersectsBounds(a, b, body(id, at))) count++;
    }
    return count;
  };
  let moves = 0;
  for (let round = 0; round < 3; round++) {
    const placed = graph.nodes.map(node => ({...node, ...positions.get(node.id)}));
    const placedById = new Map(placed.map(node => [node.id, node]));
    const bends = optimizeEdgeBends(placed, edges, routingPasses(edges.length, 2));
    const ports = computeEdgePorts(placed, edges);
    const curves = new Map<GraphEdge, EdgeCurve>(edges.map(edge => [edge, edgeGeometry(placedById.get(edge.source)!, placedById.get(edge.target)!, bends.get(edge.id) ?? 0,
      ports.get(edgePortKey(edge.id, edge.source)), ports.get(edgePortKey(edge.id, edge.target)))]));
    const routedHits = (id: string, at: PointerPosition) => {
      let count = 0;
      for (const [edge, curve] of curves) if (edge.source !== id && edge.target !== id && quadraticIntersectsBounds(curve, body(id, at, 2))) count++;
      return count;
    };
    const hits: Array<[GraphEdge, string]> = [];
    for (const [edge, curve] of curves) {
      for (const id of positions.keys()) {
        if (id === edge.source || id === edge.target) continue;
        if (quadraticIntersectsBounds(curve, body(id, positions.get(id)!))) hits.push([edge, id]);
      }
    }
    if (!hits.length) break;
    let movedThisRound = 0;
    for (const [edge, id] of hits.sort((a, b) => a[1].localeCompare(b[1]) || a[0].id.localeCompare(b[0].id))) {
      const node = byId.get(id)!;
      if (layoutNodeFixed(node, options) || (degree.get(id) ?? 0) > MOVABLE_DEGREE_LIMIT) continue;
      const centre = positions.get(id)!, curve = curves.get(edge)!;
      if (!quadraticIntersectsBounds(curve, body(id, centre))) continue;
      let closest = curve.start, best = Infinity;
      for (let i = 0; i <= 40; i++) {
        const p = quadraticPoint(curve.start, curve.control, curve.end, i / 40), d = Math.hypot(p.x - centre.x, p.y - centre.y);
        if (d < best) {best = d; closest = p;}
      }
      let dx = centre.x - closest.x, dy = centre.y - closest.y;
      if (Math.hypot(dx, dy) < 1) {dx = -(curve.end.y - curve.start.y); dy = curve.end.x - curve.start.x;}
      const length = Math.hypot(dx, dy);
      dx /= length; dy /= length;
      const hitsBefore = routedHits(id, centre), straightBefore = straightConflicts(id, centre);
      const size = sizes.get(id)!;
      const tx = -dy, ty = dx;
      const directions = [[dx, dy], [-dx, -dy], [tx, ty], [-tx, -ty], [dx + tx, dy + ty], [dx - tx, dy - ty], [-dx + tx, -dy + ty], [-dx - tx, -dy - ty]]
        .map(([x, y]) => {const l = Math.hypot(x, y); return [x / l, y / l];});
      let chosen: PointerPosition | undefined, chosenCost = Infinity;
      for (const [ux, uy] of directions) for (const step of STEPS) {
        const reach = step + Math.abs(ux) * size.width / 2 + Math.abs(uy) * size.height / 2;
        const at = {x: centre.x + ux * reach, y: centre.y + uy * reach};
        if (quadraticIntersectsBounds(curve, body(id, at, 4))) continue;
        if ([...positions.keys()].some(other => other !== id && tooClose(id, at, other, positions.get(other)!))) continue;
        const routed = routedHits(id, at);
        if (routed >= hitsBefore) continue;
        const straight = straightConflicts(id, at);
        if (straight > straightBefore) continue;
        const cost = routed * 100 + straight * 30 + reach / 10;
        if (cost < chosenCost) {chosenCost = cost; chosen = at;}
      }
      if (chosen) {positions.set(id, chosen); movedThisRound++;}
    }
    moves += movedThisRound;
    if (!movedThisRound) break;
  }
  return moves;
}
